{"file_path":"src/address.js","content":"// Cell address helpers: columns A..Z, AA..ZZ (1..702), rows 1..999 (1-3 digits).

const ADDR_RE = /^([A-Z]{1,2})([0-9]{1,3})$/

export function colIndex(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

export function colLetters(n) {
  let s = ''
  while (n > 0) {
    n--
    s = String.fromCharCode(65 + (n % 26)) + s
    n = Math.floor(n / 26)
  }
  return s
}

// Parses a raw word token (as it appeared in source) into an address
// descriptor. Always uppercases. `valid` tells whether it names a real,
// addressable cell.
export function parseAddressWord(word) {
  const upper = word.toUpperCase()
  const m = ADDR_RE.exec(upper)
  if (!m) return { raw: word, upper, valid: false }
  const row = parseInt(m[2], 10)
  if (row < 1) return { raw: word, upper, valid: false }
  return { raw: word, upper, valid: true, col: colIndex(m[1]), row, colLetters: m[1] }
}

// Strict validity check used when parsing a declared cell address from the
// sheet itself (must match exactly, already uppercased by the caller).
export function isValidDeclaredAddress(upper) {
  const m = ADDR_RE.exec(upper)
  if (!m) return false
  const row = parseInt(m[2], 10)
  return row >= 1
}

export function addressKey(col, row) {
  return colLetters(col) + row
}

export function compareAddresses(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}

export function parseKey(key) {
  const m = /^([A-Z]{1,2})([0-9]+)$/.exec(key)
  return { col: colIndex(m[1]), row: parseInt(m[2], 10) }
}
"}

