{"file_path":"src/lexer.js","content":"import { GrammarError } from './grammarError.js'

const NUM_RE = /^[0-9]+(\.[0-9]+)?/
const WORD_RE = /^[A-Za-z]+[0-9]*/

const TWO_CHAR = ['<=', '>=', '<>']
const ONE_CHAR = '^*/+-=<>(),:'

export function tokenize(str) {
  const tokens = []
  let i = 0
  while (i < str.length) {
    const ch = str[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    const rest = str.slice(i)
    const numMatch = NUM_RE.exec(rest)
    if (numMatch) {
      tokens.push({ type: 'NUM', value: numMatch[0] })
      i += numMatch[0].length
      continue
    }
    const wordMatch = WORD_RE.exec(rest)
    if (wordMatch) {
      tokens.push({ type: 'WORD', value: wordMatch[0] })
      i += wordMatch[0].length
      continue
    }
    const two = rest.slice(0, 2)
    if (TWO_CHAR.includes(two)) {
      tokens.push({ type: two, value: two })
      i += 2
      continue
    }
    if (ONE_CHAR.includes(ch)) {
      tokens.push({ type: ch, value: ch })
      i += 1
      continue
    }
    throw new GrammarError('unexpected character')
  }
  return tokens
}
"}

