{"file_path":"src/parser.js","content":"import { tokenize } from './lexer.js'
import { GrammarError } from './grammarError.js'
import { parseAddressWord } from './address.js'

const COMPARE_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const CALL_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  peekType(offset = 0) {
    const t = this.tokens[this.pos + offset]
    return t ? t.type : null
  }

  consume() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.peek()
    if (!t || t.type !== type) throw new GrammarError('expected ' + type)
    return this.consume()
  }

  parseExpr() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek() && COMPARE_OPS.has(this.peek().type)) {
      const op = this.consume().type
      const right = this.parseAdditive()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peekType() === '+' || this.peekType() === '-') {
      const op = this.consume().type
      const right = this.parseMultiplicative()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peekType() === '*' || this.peekType() === '/') {
      const op = this.consume().type
      const right = this.parsePower()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parsePower() {
    const base = this.parseUnary()
    if (this.peekType() === '^') {
      this.consume()
      const right = this.parsePower()
      return { type: 'binop', op: '^', left: base, right }
    }
    return base
  }

  parseUnary() {
    if (this.peekType() === '-' || this.peekType() === '+') {
      const op = this.consume().type
      const expr = this.parseUnary()
      return { type: 'unary', op, expr }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) throw new GrammarError('unexpected end of input')
    if (t.type === 'NUM') {
      this.consume()
      return { type: 'num', value: parseFloat(t.value) }
    }
    if (t.type === '(') {
      this.consume()
      const expr = this.parseExpr()
      this.expect(')')
      return expr
    }
    if (t.type === 'WORD') {
      const upper = t.value.toUpperCase()
      if (this.peekType(1) === '(') {
        this.consume()
        this.consume()
        const args = this.parseArgList()
        this.expect(')')
        return { type: 'call', name: upper, args }
      }
      this.consume()
      if (upper === 'TRUE') return { type: 'bool', value: true }
      if (upper === 'FALSE') return { type: 'bool', value: false }
      return { type: 'ref', addr: parseAddressWord(t.value) }
    }
    throw new GrammarError('unexpected token')
  }

  parseArgList() {
    const args = []
    if (this.peekType() === ')') return args
    args.push(this.parseArg())
    while (this.peekType() === ',') {
      this.consume()
      args.push(this.parseArg())
    }
    return args
  }

  parseArg() {
    if (
      this.peekType() === 'WORD' &&
      this.peekType(1) === ':' &&
      this.peekType(2) === 'WORD'
    ) {
      const w1 = this.consume()
      this.consume()
      const w2 = this.consume()
      return {
        type: 'range',
        from: parseAddressWord(w1.value),
        to: parseAddressWord(w2.value),
      }
    }
    return this.parseExpr()
  }
}

export function parseFormula(text) {
  try {
    const tokens = tokenize(text)
    const parser = new Parser(tokens)
    const ast = parser.parseExpr()
    if (parser.pos !== tokens.length) return { ok: false }
    return { ok: true, ast }
  } catch (e) {
    if (e instanceof GrammarError) return { ok: false }
    throw e
  }
}

export { CALL_NAMES }
"}

