    if (t.type === 'NUM') {
      this.consume()
      return { type: 'num', value: parseFloat(t.value) }
    }
    if (t.type === '(') {
      this.consume()
      const expr = this.parseExpr()
      this.expect(')')
      return expr
    }
    if (t.type === 'WORD') {
      const upper = t.value.toUpperCase()
      if (this.peekType(1) === '(') {
        this.consume()
        this.consume()
        const args = this.parseArgList()
        this.expect(')')
        return { type: 'call', name: upper, args }
      }
      this.consume()
      if (upper === 'TRUE') return { type: 'bool', value: true }
      if (upper === 'FALSE') return { type: 'bool', value: false }
      return { type: 'ref', addr: parseAddressWord(t.value) }
    }
    throw new GrammarError('unexpected token')
  }

  parseArgList() {
    const args = []
    if (this.peekType() === ')') return args
    args.push(this.parseArg())
    while (this.peekType() === ',') {
      this.consume()
      args.push(this.parseArg())
    }
