  }

  parseArg() {
    if (
      this.peekType() === 'WORD' &&
      this.peekType(1) === ':' &&
      this.peekType(2) === 'WORD'
    ) {
      const w1 = this.consume()
      this.consume()
      const w2 = this.consume()
      return {
        type: 'range',
        from: parseAddressWord(w1.value),
        to: parseAddressWord(w2.value),
      }
