    const parser = new Parser(tokens)
    const ast = parser.parseExpr()
    if (parser.pos !== tokens.length) return { ok: false }
    return { ok: true, ast }
  } catch (e) {
    if (e instanceof GrammarError) return { ok: false }
    throw e
  }
}

export { CALL_NAMES }
