{"file_path":"src/values.js","content":"// Value model: a value is one of number, text, boolean, or error.

export function numVal(v) {
  return { t: 'num', v }
}
export function textVal(v) {
  return { t: 'text', v }
}
export function boolVal(v) {
  return { t: 'bool', v }
}
export function errVal(v) {
  return { t: 'err', v }
}

export function toNumber(val) {
  if (val.t === 'num') return val
  if (val.t === 'bool') return numVal(val.v ? 1 : 0)
  if (val.t === 'text') return errVal('#VALUE!')
  return val // already an error
}

const KIND_RANK = { num: 0, text: 1, bool: 2 }

// Compares two non-error values per the cross-kind ordering rules.
export function compareValues(a, b) {
  if (a.t === b.t) {
    if (a.t === 'num') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
    if (a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
    if (a.t === 'bool') return (a.v ? 1 : 0) - (b.v ? 1 : 0)
  }
  return KIND_RANK[a.t] - KIND_RANK[b.t]
}

export function formatNumber(n) {
  if (Object.is(n, -0)) n = 0
  const rounded = Number(n.toPrecision(10))
  return String(rounded)
}

export function formatValue(val) {
  if (val.t === 'num') return formatNumber(val.v)
  if (val.t === 'text') return val.v
  if (val.t === 'bool') return val.v ? 'TRUE' : 'FALSE'
  return val.v
}
"}

