{"file_path":"src/evaluate.js","content":"import { parseFormula } from './parser.js'
import { colLetters, colIndex } from './address.js'
import { numVal, textVal, errVal, boolVal, toNumber, compareValues } from './values.js'

const ERROR_TOKENS = new Set([
  '#DIV/0!',
  '#REF!',
  '#VALUE!',
  '#CYCLE!',
  '#NAME?',
  '#ERR!',
])
const LITERAL_NUM_RE = /^-?[0-9]+(\.[0-9]+)?$/

const COMPARE_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

function finiteOrDivZero(n) {
  return Number.isFinite(n) ? numVal(n) : errVal('#DIV/0!')
}

class Evaluator {
  constructor(sheet) {
    this.sheet = sheet // Map key -> content string
    this.cache = new Map()
    this.visiting = new Set()
  }

  evaluateCell(key) {
    if (this.cache.has(key)) return this.cache.get(key)
    if (!this.sheet.has(key)) {
      const v = numVal(0)
      this.cache.set(key, v)
      return v
    }
    if (this.visiting.has(key)) return errVal('#CYCLE!')
    this.visiting.add(key)
    const content = this.sheet.get(key)
    const value = this.computeContent(content)
    this.visiting.delete(key)
    this.cache.set(key, value)
    return value
  }

  computeContent(content) {
    if (content === '') return numVal(0)
    if (content[0] === '=') {
      const parsed = parseFormula(content.slice(1))
      if (!parsed.ok) return errVal('#ERR!')
      return this.evalExpr(parsed.ast)
    }
    if (LITERAL_NUM_RE.test(content)) return numVal(parseFloat(content))
    if (ERROR_TOKENS.has(content)) return errVal(content)
    return textVal(content)
  }

  evalExpr(node) {
    switch (node.type) {
      case 'num':
        return numVal(node.value)
      case 'bool':
        return boolVal(node.value)
      case 'ref':
        if (!node.addr.valid) return errVal('#REF!')
        return this.evaluateCell(node.addr.upper)
      case 'unary': {
        const v = this.evalExpr(node.expr)
        const n = toNumber(v)
        if (n.t === 'err') return n
        return numVal(node.op === '-' ? -n.v : n.v)
      }
      case 'binop':
        return this.evalBinop(node)
      case 'call':
        return this.evalCall(node)
      default:
        throw new Error('unknown node ' + node.type)
    }
  }

  evalBinop(node) {
    const a = this.evalExpr(node.left)
    const b = this.evalExpr(node.right)
    if (COMPARE_OPS.has(node.op)) {
      if (a.t === 'err') return a
      if (b.t === 'err') return b
      const c = compareValues(a, b)
      switch (node.op) {
        case '=':
          return boolVal(c === 0)
        case '<>':
          return boolVal(c !== 0)
        case '<':
          return boolVal(c < 0)
        case '<=':
          return boolVal(c <= 0)
        case '>':
          return boolVal(c > 0)
        case '>=':
          return boolVal(c >= 0)
      }
    }
    if (a.t === 'err') return a
    const na = toNumber(a)
    if (na.t === 'err') return na
    if (b.t === 'err') return b
    const nb = toNumber(b)
    if (nb.t === 'err') return nb
    switch (node.op) {
      case '+':
        return finiteOrDivZero(na.v + nb.v)
      case '-':
        return finiteOrDivZero(na.v - nb.v)
      case '*':
        return finiteOrDivZero(na.v * nb.v)
      case '/':
        if (nb.v === 0) return errVal('#DIV/0!')
        return finiteOrDivZero(na.v / nb.v)
      case '^':
        return finiteOrDivZero(Math.pow(na.v, nb.v))
    }
    throw new Error('unknown op ' + node.op)
  }

  // Flattens an argument node (Expr or Range) into an ordered list of raw
  // values, expanding ranges into their covered cells.
  expandArg(node) {
    if (node.type === 'range') {
      const { from, to } = node
      if (!from.valid || !to.valid) return [errVal('#REF!')]
      const c1 = Math.min(from.col, to.col)
      const c2 = Math.max(from.col, to.col)
      const r1 = Math.min(from.row, to.row)
      const r2 = Math.max(from.row, to.row)
      const out = []
      for (let c = c1; c <= c2; c++) {
        for (let r = r1; r <= r2; r++) {
          out.push(this.evaluateCell(colLetters(c) + r))
        }
      }
      return out
    }
    return [this.evalExpr(node)]
  }

  expandArgs(nodes) {
    const out = []
    for (const n of nodes) out.push(...this.expandArg(n))
    return out
  }

  // A single-value argument: for ABS and IF's positions. Range arguments
  // must resolve to exactly one covered cell.
  evalArgSingle(node) {
    const list = this.expandArg(node)
    for (const v of list) if (v.t === 'err') return v
    if (list.length !== 1) return errVal('#ERR!')
    return list[0]
  }

  evalCall(node) {
    const name = node.name
    const args = node.args
    if (name === 'SUM' || name === 'MIN' || name === 'MAX' || name === 'AVG') {
      if (args.length < 1) return errVal('#ERR!')
      const list = this.expandArgs(args)
      const nums = []
      for (const v of list) {
        const n = toNumber(v)
        if (n.t === 'err') return n
        nums.push(n.v)
      }
      if (name === 'SUM') return finiteOrDivZero(nums.reduce((a, b) => a + b, 0))
      if (name === 'MIN') return finiteOrDivZero(Math.min(...nums))
      if (name === 'MAX') return finiteOrDivZero(Math.max(...nums))
      // AVG
      const sum = nums.reduce((a, b) => a + b, 0)
      return finiteOrDivZero(sum / nums.length)
    }
    if (name === 'COUNT') {
      if (args.length < 1) return errVal('#ERR!')
      const list = this.expandArgs(args)
      for (const v of list) if (v.t === 'err') return v
      return numVal(list.filter((v) => v.t === 'num').length)
    }
    if (name === 'ABS') {
      if (args.length !== 1) return errVal('#ERR!')
      const v = this.evalArgSingle(args[0])
      if (v.t === 'err') return v
      const n = toNumber(v)
      if (n.t === 'err') return n
      return finiteOrDivZero(Math.abs(n.v))
    }
    if (name === 'IF') {
      if (args.length !== 3) return errVal('#ERR!')
      const cond = this.evalArgSingle(args[0])
      if (cond.t === 'err') return cond
      let truthy
      if (cond.t === 'bool') truthy = cond.v
      else if (cond.t === 'num') truthy = cond.v !== 0
      else return errVal('#VALUE!')
      const branch = truthy ? args[1] : args[2]
      return this.evalArgSingle(branch)
    }
    return errVal('#NAME?')
  }
}

export function evaluateSheet(sheet) {
  const evaluator = new Evaluator(sheet)
  const result = new Map()
  for (const key of sheet.keys()) result.set(key, evaluator.evaluateCell(key))
  return result
}
"}

