      for (const arg of node.args) walk(arg, set)
      return
    case 'num':
    case 'bool':
      return
    default:
      throw new Error('unknown node ' + node.type)
  }
}

// Returns the sorted list of distinct addresses a cell's content names
// directly (ranges expanded). A literal, or a formula the grammar does not
// accept, names none.
export function cellDeps(content) {
  if (content === '' || content[0] !== '=') return []
  const parsed = parseFormula(content.slice(1))
  if (!parsed.ok) return []
  const set = new Set()
  walk(parsed.ast, set)
  const keys = [...set]
  keys.sort((a, b) => compareAddresses(parseKey(a), parseKey(b)))
  return keys
}
"}

