export class SheetError extends Error {}

// Parses the sheet text into a Map of address -> content string.
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    const stripped = line.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped[0] === '#') continue

    let idx = -1
    for (let j = 0; j < stripped.length; j++) {
      const c = stripped[j]
      if (c === ' ' || c === '\t') {
        idx = j
        break
      }
    }
    let address, content
    if (idx === -1) {
      address = stripped
      content = ''
    } else {
      address = stripped.slice(0, idx)
      let k = idx
      while (k < stripped.length && (stripped[k] === ' ' || stripped[k] === '\t')) k++
      content = stripped.slice(k)
    }

    const upper = address.toUpperCase()
    if (!isValidDeclaredAddress(upper)) {
      throw new SheetError(`line ${lineNo}: invalid cell address ${upper}`)
    }
    if (cells.has(upper)) {
      throw new SheetError(`line ${lineNo}: cell ${upper} is declared twice`)
    }
    cells.set(upper, content)
  }
  return cells
}
"}

