{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import fs from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { evaluateSheet } from './evaluate.js'
import { formatValue } from './values.js'
import { cellDeps } from './deps.js'
import { parseKey, compareAddresses } from './address.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exitCode = 2
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'values' && mode !== 'deps' || process.argv.length !== 3) {
    fail('usage: cli.js values|deps')
    return
  }

  let input
  try {
    input = fs.readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(e.message)
      return
    }
    throw e
  }

  const keys = [...cells.keys()]
  keys.sort((a, b) => compareAddresses(parseKey(a), parseKey(b)))

  let out = ''
  if (mode === 'values') {
    const values = evaluateSheet(cells)
    for (const key of keys) {
      out += `${key}=${formatValue(values.get(key))}\n`
    }
  } else {
    for (const key of keys) {
      const deps = cellDeps(cells.get(key))
      out += `${key}:${deps.map((d) => ' ' + d).join('')}\n`
    }
  }
  process.stdout.write(out)
}

main()
"}

